require_once __DIR__.'/../includes/auth.php';require_role(['super_admin','manager','trainer']);$bid=current_branch_id();$myTrainerId=user()['role']==='trainer'?(int)(query_value('SELECT id FROM trainers WHERE user_id=?',[user()['id']])?:0):0;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';
 if($a==='add'){
  $trainerId=user()['role']==='trainer'?$myTrainerId:($_POST['trainer_id']?:null);
  $memberId=(int)$_POST['member_id'];
  if(user()['role']==='trainer' && !(int)query_value('SELECT COUNT(*) FROM members WHERE id=? AND branch_id=? AND trainer_id=?',[$memberId,$bid,$myTrainerId])){http_response_code(403);exit('403 — You can create diet plans only for assigned members.');}
  $stmt=db()->prepare("INSERT INTO diet_plans(branch_id,member_id,trainer_id,title,goal,daily_calories,protein_g,carbs_g,fat_g,start_date,end_date,status,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,'active',?)");
  $stmt->execute([$bid,$memberId,$trainerId,trim($_POST['title']),trim($_POST['goal']??''),$_POST['daily_calories']?:null,$_POST['protein_g']?:null,$_POST['carbs_g']?:null,$_POST['fat_g']?:null,$_POST['start_date']?:null,$_POST['end_date']?:null,trim($_POST['notes']??'')]);
  $id=(int)db()->lastInsertId();
  $mealStmt=db()->prepare("INSERT INTO diet_items(diet_plan_id,meal_name,item_name,notes) VALUES(?,?,?,?)");
  foreach(['Breakfast','Lunch','Snack','Dinner'] as $meal){$key=strtolower($meal);$text=trim($_POST[$key]??'');if($text!=='')$mealStmt->execute([$id,$meal,$text,null]);}
  audit_log('diet.created','diet_plan',$id,'Diet plan created');
  flash('success','Diet plan created.');redirect('app/diet_plans.php');
 }
 if($a==='status'){if(user()['role']==='trainer' && !(int)query_value('SELECT COUNT(*) FROM diet_plans WHERE id=? AND branch_id=? AND trainer_id=?',[(int)$_POST['id'],$bid,$myTrainerId])){http_response_code(403);exit('403');}db()->prepare("UPDATE diet_plans SET status=? WHERE id=? AND branch_id=?")->execute([$_POST['status'],(int)$_POST['id'],$bid]);audit_log('diet.status','diet_plan',(int)$_POST['id'],'Diet plan status changed');flash('success','Diet plan status updated.');redirect('app/diet_plans.php');}
}
$filter=user()['role']==='trainer'?' AND d.trainer_id=?':'';$rowParams=[$bid];if($filter)$rowParams[]=$myTrainerId;
$rows=query_all("SELECT d.*,CONCAT(m.first_name,' ',m.last_name) member_name,m.member_code,t.name trainer_name,(SELECT COUNT(*) FROM diet_items i WHERE i.diet_plan_id=d.id) meals FROM diet_plans d JOIN members m ON m.id=d.member_id LEFT JOIN trainers t ON t.id=d.trainer_id WHERE d.branch_id=? $filter ORDER BY d.created_at DESC",$rowParams);
if(user()['role']==='trainer'){$members=query_all("SELECT id,member_code,CONCAT(first_name,' ',last_name) name FROM members WHERE branch_id=? AND trainer_id=? AND status='active' AND membership_end>=CURDATE() ORDER BY first_name",[$bid,$myTrainerId]);$trainers=query_all("SELECT id,name FROM trainers WHERE id=? AND branch_id=?",[$myTrainerId,$bid]);}else{$members=query_all("SELECT id,member_code,CONCAT(first_name,' ',last_name) name FROM members WHERE branch_id=? AND status='active' AND membership_end>=CURDATE() ORDER BY first_name",[$bid]);$trainers=query_all("SELECT id,name FROM trainers WHERE branch_id=? AND status='active' ORDER BY name",[$bid]);}
$pageTitle='Diet & Nutrition Plans';include __DIR__.'/../includes/header.php';?>
