<div class="metric-strip compact"><div class="metric-box"><small>Calories</small><strong><?= (int)$d['daily_calories'] ?: '—' ?></strong></div><div class="metric-box"><small>Protein</small><strong><?= $d['protein_g']?(int)$d['protein_g'].'g':'—' ?></strong></div></div>
<p class="small mt-3 mb-2"><?= e($d['goal']?:'General nutrition') ?> · Coach <?= e($d['trainer_name']??'Unassigned') ?></p>
